import { execa } from 'execa';
import { TestDinoError } from '../errors.js';

const LIST_TIMEOUT_MS = 60_000;

export type ListRunner = (args: string[]) => Promise<string>;

// Ours go last: Playwright keeps the final --reporter, so a user's
// `--reporter=html` after `--` must not replace the JSON parsed here.
const defaultListRunner: ListRunner = async (args) => {
  const result = await execa('npx', ['playwright', 'test', ...args, '--list', '--reporter=json'], {
    timeout: LIST_TIMEOUT_MS,
    reject: false,
    stdin: 'ignore',
  });
  if (typeof result.stdout !== 'string' || result.stdout.trim() === '') {
    throw new Error(`playwright --list produced no output (exit ${result.exitCode})`);
  }
  return result.stdout;
};

interface ListSuite {
  specs?: Array<{ id?: string; tests?: unknown[] }>;
  suites?: ListSuite[];
}

interface ListReport {
  suites?: ListSuite[];
  errors?: Array<{ message?: string }>;
}

function countReportTests(report: ListReport): number {
  const walk = (suite: ListSuite): number =>
    (suite.specs ?? []).reduce((n, spec) => n + (spec.tests ?? []).length, 0) +
    (suite.suites ?? []).reduce((n, child) => n + walk(child), 0);
  return (report.suites ?? []).reduce((n, suite) => n + walk(suite), 0);
}

// A --list spec is one test in one project, and its id is the test id
// TestDino stores, so ids say WHICH tests matched, not only how many.
function collectTestIds(report: ListReport): string[] {
  const ids: string[] = [];
  const walk = (suite: ListSuite): void => {
    for (const spec of suite.specs ?? []) {
      if (spec.id && (spec.tests ?? []).length > 0) ids.push(spec.id);
    }
    (suite.suites ?? []).forEach(walk);
  };
  (report.suites ?? []).forEach(walk);
  return ids;
}

export function countTests(listJson: string): number {
  return countReportTests(JSON.parse(listJson) as ListReport);
}

export interface SelectionMatch {
  matched: number;
  ids?: string[];
  // False when the check could not run; callers must not read that as zero.
  checked: boolean;
  reason?: string;
}

// Playwright proceeds with whatever matched and exits 0 even when nothing
// did, so the CLI has to compare the selection against this checkout itself.
export async function countSelectedTests(
  selectionPath: string,
  playwrightArgs: string[],
  listRunner: ListRunner = defaultListRunner
): Promise<SelectionMatch> {
  let report: ListReport;
  try {
    report = JSON.parse(await listRunner([...playwrightArgs, `--test-list=${selectionPath}`])) as ListReport;
  } catch (error) {
    return { matched: 0, checked: false, reason: error instanceof Error ? error.message : String(error) };
  }
  // A spec that fails to load lists nothing and puts the error in the report,
  // not on stderr; without this it reads as "every selected test was renamed".
  const loadError = report.errors?.[0]?.message;
  if (loadError) {
    throw new TestDinoError(`Playwright could not load the selected tests:\n${loadError}`);
  }
  return { matched: countReportTests(report), ids: collectTestIds(report), checked: true };
}
