import { ConfigLoader } from '../config-loader.js';
import { ConfigDetector } from '../config-detector.js';
import { ConfigMerger } from '../config-merger.js';
import { ArgFilter } from '../arg-filter.js';
import { TempConfigManager } from '../temp-config.js';
import { PlaywrightSpawner } from '../playwright-spawner.js';
import { Logger } from '../logger.js';
import { RerunSplitConflictError, TestDinoError } from '../errors.js';
import { fetchRerunSelection } from '../rerun/client.js';
import {
  conflictingSelector,
  hasShardFlag,
  misplacedRerunFlag,
  readInstalledPlaywrightVersion,
  SelectionFile,
  supportsTestList,
} from '../rerun/prepare.js';
import { countSelectedTests } from '../rerun/verify.js';
import { isRerunScope, RERUN_SCOPES } from '../rerun/types.js';
import type { RerunScope, RerunSelection } from '../rerun/types.js';
import type { CliOptions, MergedConfig } from '../types.js';
import { DEFAULT_SERVER_URL } from '../../types/index.js';
import type { PlaywrightSpawnResult } from '../playwright-spawner.js';

const SCOPE_LABELS: Record<RerunScope, string> = {
  failed: 'failed',
  flaky: 'flaky',
  'failed-and-flaky': 'failed and flaky',
};

interface RerunPlan {
  scope: RerunScope;
  fromRun: string;
  token: string;
  testIds?: string[];
  excludeTestIds?: string[];
}

export class TestCommand {
  private configLoader: ConfigLoader;
  private configDetector: ConfigDetector;
  private configMerger: ConfigMerger;
  private argFilter: ArgFilter;
  private tempConfigManager: TempConfigManager;
  private playwrightSpawner: PlaywrightSpawner;
  private logger: Logger;

  constructor(
    configLoader?: ConfigLoader,
    configDetector?: ConfigDetector,
    configMerger?: ConfigMerger,
    argFilter?: ArgFilter,
    tempConfigManager?: TempConfigManager,
    playwrightSpawner?: PlaywrightSpawner,
    logger?: Logger
  ) {
    this.configLoader = configLoader || new ConfigLoader();
    this.configDetector = configDetector || new ConfigDetector();
    this.configMerger = configMerger || new ConfigMerger();
    this.argFilter = argFilter || new ArgFilter();
    this.tempConfigManager = tempConfigManager || new TempConfigManager(logger);
    this.playwrightSpawner = playwrightSpawner || new PlaywrightSpawner(logger);
    this.logger = logger || new Logger();
  }

  async execute(options: CliOptions, args: string[]): Promise<PlaywrightSpawnResult> {
    let tempConfigPath: string | undefined;
    const selectionFile = new SelectionFile();

    try {
      // 1. Load testdino.config.[ts|js]
      const testdinoConfigResult = await this.configLoader.load();

      // 2. Detect playwright.config.[ts|js] and TestdinoReporter
      const playwrightConfigResult = await this.configDetector.detect();

      // 3. Get environment variables
      const envConfig = ConfigMerger.getEnvConfig();

      // 4. Merge all configs with proper priority
      const mergedConfig = this.configMerger.merge({
        env: envConfig,
        playwrightConfig: playwrightConfigResult.options,
        testdinoConfig: testdinoConfigResult.config,
        cliOptions: options,
      });

      // 5. Filter TestDino-specific arguments
      let filteredArgs = this.argFilter.filter(args);

      // 6. Re-run selection: resolve the source run's failed set server-side and
      //    hand it to Playwright as --test-list. Refusals happen before any
      //    network call; a resolved empty set exits 0 without a run.
      const misplaced = misplacedRerunFlag(filteredArgs);
      if (misplaced) {
        throw new TestDinoError(
          `${misplaced} must come before "--": everything after it goes to Playwright unchanged.\n\nUse: npx tdpw test --rerun failed --from-run <runId> -- <playwright args>`
        );
      }
      if (options.rerun !== undefined) {
        const selection = await this.resolveRerunSelection(options, mergedConfig, filteredArgs);
        if (selection === null) {
          return { exitCode: 0, success: true };
        }
        const selectionPath = selectionFile.write(selection.testList);
        const locationArgs = selection.locations ?? [];
        await this.verifyRerunSelection(selectionPath, [...filteredArgs, ...locationArgs], selection);
        filteredArgs = [...filteredArgs, ...locationArgs, `--test-list=${selectionPath}`];
        mergedConfig.rerunOf = selection.sourceRunId;
      }

      // 7. Create temp config file
      const tempConfigInfo = this.tempConfigManager.create(mergedConfig);
      tempConfigPath = tempConfigInfo.path;

      // 8. Spawn Playwright with filtered args and config
      const result = await this.playwrightSpawner.spawn({
        args: filteredArgs,
        tempConfigPath,
        config: mergedConfig,
      });

      return result;
    } finally {
      // 9. Always cleanup temp files
      if (tempConfigPath) {
        this.tempConfigManager.cleanup(tempConfigPath);
      }
      selectionFile.cleanup();
    }
  }

  private planRerun(options: CliOptions, mergedConfig: MergedConfig, playwrightArgs: string[]): RerunPlan {
    const scope = String(options.rerun);
    if (!isRerunScope(scope)) {
      throw new TestDinoError(`--rerun must be one of: ${RERUN_SCOPES.join(', ')} (got "${scope}").`);
    }
    if (!options.fromRun) {
      throw new TestDinoError('--rerun requires --from-run <runId>: the run whose failures should be re-executed.');
    }
    // ConfigMerger.validate already refused a missing token; this narrows the type.
    if (!mergedConfig.token) {
      throw new TestDinoError('--rerun needs a TestDino token (--token or TESTDINO_TOKEN).');
    }
    if (mergedConfig.split !== undefined || mergedConfig.splitId !== undefined) {
      throw new RerunSplitConflictError(mergedConfig.split !== undefined ? '--split' : '--split-id');
    }
    const conflict = conflictingSelector(playwrightArgs);
    if (conflict) {
      throw new TestDinoError(
        `--rerun cannot be combined with ${conflict}: the re-run selection already decides which tests run.`
      );
    }
    if (hasShardFlag(playwrightArgs)) {
      throw new TestDinoError(
        '--rerun cannot be combined with --shard: a re-run is a handful of tests, so every other shard would find nothing and fail.'
      );
    }
    const playwrightVersion = readInstalledPlaywrightVersion();
    if (!supportsTestList(playwrightVersion)) {
      throw new TestDinoError(
        `--rerun needs Playwright 1.56 or newer for --test-list (found ${playwrightVersion ?? 'no readable version'}). On older releases the selection cannot be passed safely and the whole suite would run instead.`
      );
    }
    return {
      scope,
      fromRun: options.fromRun,
      token: mergedConfig.token,
      testIds: splitIds(options.testIds),
      excludeTestIds: splitIds(options.excludeIds),
    };
  }

  // null means "nothing to re-run" — reported, not an error.
  private async resolveRerunSelection(
    options: CliOptions,
    mergedConfig: MergedConfig,
    playwrightArgs: string[]
  ): Promise<RerunSelection | null> {
    const plan = this.planRerun(options, mergedConfig, playwrightArgs);
    const selection = await fetchRerunSelection({
      serverUrl: mergedConfig.serverUrl ?? DEFAULT_SERVER_URL,
      token: plan.token,
      runId: plan.fromRun,
      scope: plan.scope,
      testIds: plan.testIds,
      excludeTestIds: plan.excludeTestIds,
    });
    const { selected, inScope, missingTestIds, unrenderableTests } = selection.resolution;
    const what = plan.testIds ? 'selected' : SCOPE_LABELS[plan.scope];

    for (const test of unrenderableTests ?? []) {
      this.logger.warn(`TestDino re-run: "${test.title}" cannot be selected by its title or location; run it by hand.`);
    }
    if (missingTestIds?.length) {
      this.logger.warn(
        `TestDino re-run: ${missingTestIds.length} requested test id(s) are not in run ${plan.fromRun}.`
      );
    }
    if (selected === 0) {
      this.logger.info(`TestDino re-run: nothing to re-run — run ${plan.fromRun} has no ${what} tests in scope.`);
      return null;
    }
    this.logger.info(`TestDino re-run: ${selected} of ${inScope} ${what} test(s) from run ${plan.fromRun}`);
    return selection;
  }

  // Playwright runs whatever matched and exits 0 even when nothing did, so a
  // zero match must be refused here or a stale selection reports green.
  private async verifyRerunSelection(
    selectionPath: string,
    playwrightArgs: string[],
    selection: RerunSelection
  ): Promise<void> {
    const selected = selection.testList.length;
    const match = await countSelectedTests(selectionPath, playwrightArgs);
    if (!match.checked) {
      this.logger.warn(
        `TestDino re-run: could not verify the selection against this checkout (${match.reason ?? 'unknown'}); running it as-is.`
      );
      return;
    }
    if (selection.testIds?.length && match.ids) {
      this.checkRerunIdentity(selection, match.ids);
      return;
    }
    if (match.matched === selected) return;
    if (match.matched === 0) {
      throw new TestDinoError(
        `None of the ${selected} selected test(s) exist in this checkout: renamed, moved or deleted since run ${selection.sourceRunId}, or excluded by the Playwright args you passed (--project, a file filter). Nothing was run.`
      );
    }
    if (match.matched > selected) {
      throw new TestDinoError(
        `The selection matched ${match.matched} tests but ${selected} were selected, so it is broader than intended. Run the tests by hand and report run ${selection.sourceRunId} to TestDino.`
      );
    }
    this.logger.warn(
      `TestDino re-run: ${selected - match.matched} of ${selected} selected test(s) do not exist in this checkout (renamed, moved, deleted, or excluded by the Playwright args you passed) and will be skipped.`
    );
  }

  // A count can hide a swap: on a later commit a placed test's line may now hold
  // a different test. An unexpected id refuses; a missing one only warns.
  private checkRerunIdentity(selection: RerunSelection, listed: string[]): void {
    const expected = new Set(selection.testIds);
    const extra = listed.filter((id) => !expected.has(id));
    if (extra.length > 0) {
      throw new TestDinoError(
        `The selection would also run ${extra.length} test(s) that were not selected from run ${selection.sourceRunId}, most likely because the code changed since that run. Nothing was run; re-run these tests by hand.`
      );
    }
    const found = new Set(listed);
    const selected = selection.testIds?.length ?? 0;
    const missing = (selection.testIds ?? []).filter((id) => !found.has(id)).length;
    if (missing === selected) {
      throw new TestDinoError(
        `None of the ${selected} selected test(s) exist in this checkout: renamed, moved or deleted since run ${selection.sourceRunId}, or excluded by the Playwright args you passed (--project, a file filter). Nothing was run.`
      );
    }
    if (missing > 0) {
      this.logger.warn(
        `TestDino re-run: ${missing} of ${selected} selected test(s) do not exist in this checkout (renamed, moved, deleted, or excluded by the Playwright args you passed) and will be skipped.`
      );
    }
  }
}

function splitIds(csv: string | undefined): string[] | undefined {
  const ids = (csv ?? '')
    .split(',')
    .map((id) => id.trim())
    .filter((id) => id !== '');
  return ids.length > 0 ? ids : undefined;
}
