export const RERUN_SCOPES = ['failed', 'flaky', 'failed-and-flaky'] as const;

export type RerunScope = (typeof RERUN_SCOPES)[number];

export function isRerunScope(value: string): value is RerunScope {
  return (RERUN_SCOPES as readonly string[]).includes(value);
}

export interface RerunSelection {
  sourceRunId: string;
  testList: string[];
  // The Playwright test id of each testList line; absent from older servers.
  testIds?: string[];
  // Positional args Playwright ANDs with --test-list; they narrow a shortened
  // line to the one test it stands for.
  locations?: string[];
  resolution: {
    selected: number;
    inScope: number;
    missingTestIds?: string[];
    unrenderableTests?: Array<{ pwTestId: string; title: string }>;
  };
}
